from openai import OpenAI
client = OpenAI()

# 电商客服完整架构：意图路由 + RAG + 订单/物流集成 + 情感识别转人工
# 第1步：意图路由（小模型，便宜又快）
CLS_TOOL = {
    "type": "function",
    "function": {
        "name": "classify",
        "parameters": {"type": "object",
            "properties": {"c": {"enum": ["presale", "aftersale", "logistics", "other"]}}},
    },
}

def route(msg: str) -> str:
    r = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": f"分类意图: {msg}"}],
        tools=[CLS_TOOL],
        tool_choice={"type": "function", "function": {"name": "classify"}})
    return r.choices[0].message.tool_calls[0].function.arguments

# 第2步：按意图取上下文——售前走 RAG、售后查订单、物流查物流
def ctx(c, msg):
    if c == "presale":   return rag_search(msg)
    if c == "aftersale": return query_order("U1001")
    if c == "logistics": return query_logistics("U1001")
    return "无"

# 第3步：情感识别——负面/愤怒直接转人工，比关键词更准
def sentiment(msg: str) -> str:
    s = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": f"判断情绪(positive/negative): {msg}"}]).choices[0].message.content
    return "transfer_human" if "negative" in s else "auto"

def handle(msg: str):
    c = route(msg)
    if sentiment(msg) == "transfer_human":
        return "转人工（情绪负面）"
    context = ctx(c, msg)
    return client.chat.completions.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": f"基于[{context}]回答: {msg}"}]).choices[0].message.content

print(handle("我的订单啥时候到？"))   # 走 logistics 分支
